const original = $('Build Conversation Context2').first().json;
const extracted = $input.first().json || {};

return [{
  json: {
    ...original,
    attachment_text: extracted.attachment_text || '',
    attachment_summary: extracted.attachment_summary || '',
    attachment_extraction_method: extracted.extraction_method || 'none'
  }
}];

const input = $input.first().json;
const body = input.body || input;

const text = String(body.text || '').trim();
const sender = body.sender || 'Unknown';
const conversationId = body.conversationId || body.sessionId || body.userId || body.sender || `conv_${Date.now()}`;
const history = Array.isArray(body.history) ? body.history : [];

const fileUrl = body.file_url || null;
const fileType = body.file_type || '';
const fileName = body.file_name || '';

const hasPdf = fileType === 'application/pdf' || fileName.toLowerCase().endsWith('.pdf');
const hasImage = fileType.startsWith('image/') || ['.png', '.jpg', '.jpeg', '.webp', '.gif'].some(ext => fileName.toLowerCase().endsWith(ext));
const hasAttachment = Boolean(fileUrl || hasPdf || hasImage);

return [{
  json: {
    sender,
    conversationId,
    message: text,
    history,
    file_url: fileUrl,
    file_type: fileType,
    file_name: fileName,
    hasPdf,
    hasImage,
    hasAttachment,
    messageId: body.messageId || '',
    timestamp: body.timestamp || new Date().toISOString()
  }
}];

const data = $input.first().json;
const normalizedText = (data.message || '').toLowerCase().trim().replace(/\s+/g, ' ');
const errorMatch = normalizedText.match(/\b(400|401|403|404|408|409|429|500|502|503|504)\b/);

let attachmentHint = 'none';
if (data.hasPdf) attachmentHint = 'pdf';
else if (data.hasImage) attachmentHint = 'image';

return [{
  json: {
    ...data,
    normalizedText,
    possibleErrorCode: errorMatch ? errorMatch[1] : null,
    attachmentHint,
    isEmptyMessage: !normalizedText && !data.hasAttachment
  }
}];

const item = $input.first().json;

const messagesRaw = item.messages || item.data?.messages || item.memory || item.chat_memory || [];
const memoryRows = Array.isArray(messagesRaw) ? messagesRaw : [];

function extractTicketId(text) {
  if (!text) return null;
  const match = String(text).match(/ticket[_\-\s]?id[:\s]+(ticket_[a-zA-Z0-9_-]+)/i);
  return match ? match[1] : null;
}

const historyFromDb = memoryRows.map(row => {
  const userText =
    row.role === 'user'
      ? (row.user_query || row.user_message || row.message_text || row.text || '')
      : '';

  const assistantText =
    row.role === 'assistant'
      ? (row.assistant_message || row.message_text || row.text || '')
      : '';

  const matchedIssue = row.matched_issue || null;
  const explicitTicketId = row.ticket_id || null;
  const textTicketId = extractTicketId(userText || assistantText);

  const trustedTicketId =
    matchedIssue === 'manual_ticket' ||
    matchedIssue === 'existing_ticket_reused' ||
    /support ticket/i.test(userText || assistantText) ||
    /ticket id/i.test(userText || assistantText)
      ? (explicitTicketId || textTicketId)
      : null;

  return {
    role: row.role || 'user',
    text: row.role === 'user' ? userText : assistantText,
    message: row.role === 'user' ? userText : assistantText,
    user_message: row.role === 'user' ? (row.user_message || row.user_query || row.message_text || '') : '',
    user_query: row.role === 'user' ? (row.user_query || row.user_message || row.message_text || '') : '',
    assistant_message: row.role === 'assistant' ? (row.assistant_message || row.message_text || '') : '',
    intent: row.intent || null,
    matched_issue: matchedIssue,
    issue_summary: row.issue_summary || null,
    attachment_summary: row.attachment_summary || null,
    ticket_id: trustedTicketId,
    file_url: row.file_url || null,
    file_type: row.file_type || null,
    file_name: row.file_name || null,
    created_at: row.created_at || null
  };
}).filter(x => x.user_message || x.assistant_message || x.attachment_summary);

const incomingHistory = Array.isArray(item.history) ? item.history : [];
const history = historyFromDb.length > 0 ? historyFromDb : incomingHistory;

let latestTicketEntry = null;
for (let i = history.length - 1; i >= 0; i--) {
  const h = history[i];
  if (
    h.ticket_id &&
    (h.matched_issue === 'manual_ticket' || h.matched_issue === 'existing_ticket_reused')
  ) {
    latestTicketEntry = h;
    break;
  }
}

return [{
  json: {
    ...item,
    history,
    latest_ticket_id: latestTicketEntry ? latestTicketEntry.ticket_id : null,
    latest_ticket_message: latestTicketEntry ? (latestTicketEntry.user_message || latestTicketEntry.assistant_message || latestTicketEntry.text) : null,
    has_existing_ticket: !!latestTicketEntry
  }
}];

return [{
  json: {
    ...$json,
    apiPayload: {
      response: 'Please type your issue or upload a screenshot/PDF so I can help you.',
      sender: 'AI Assistant',
      category: 'empty_message',
      originalMessageId: $json.messageId || '',
      conversationId: $json.conversationId || ''
    }
  }
}];

let reply = '';

if ($json.fast_intent === 'greeting') {
  reply = 'Hello! How can I help you today?';
} else if ($json.fast_intent === 'acknowledgement') {
  reply = 'You’re welcome. Let me know if you need anything else.';
}

return [{
  json: {
    ...$json,
    final_response_text: reply,
    intent: $json.fast_intent,
    matched_issue: $json.fast_intent
  }
}];

let msg = String($json.message || $json.text || '').trim().toLowerCase();

// remove extra spaces
msg = msg.replace(/\s+/g, ' ');

// collapse repeated letters: hiiiiii -> hii, heyyyy -> heyy
msg = msg.replace(/([a-z])\1{2,}/g, '$1$1');

// remove common punctuation noise
msg = msg.replace(/[!?.,]+/g, '').trim();

const greetings = [
  'hi', 'hii', 'hello', 'hey', 'heyy', 'gm',
  'good morning', 'good afternoon', 'good evening'
];

const acknowledgements = [
  'ok', 'okay', 'okk', 'thanks', 'thank you', 'thx',
  'got it', 'cool', 'alright', 'noted', 'fine'
];

let fast_intent = 'other';

if (greetings.some(x => msg === x || msg.startsWith(x + ' '))) {
  fast_intent = 'greeting';
} else if (acknowledgements.some(x => msg === x || msg.startsWith(x + ' '))) {
  fast_intent = 'acknowledgement';
}

return [{
  json: {
    ...$json,
    normalized_message: msg,
    fast_intent
  }
}];

const history = Array.isArray($json.history) ? $json.history : [];
const currentMessage = ($json.message || '').toLowerCase().trim();

// STRICTLY only previous USER messages
const userMessages = history
  .filter(item => item.role === 'user')
  .map(item => item.user_query || item.user_message || item.message || item.text || '')
  .filter(Boolean)
  .filter(msg => msg.toLowerCase().trim() !== currentMessage);

const lastUserMessage = userMessages[userMessages.length - 1] || '';

function extractTopic(text) {
  const stopWords = [
    'did','i','ask','anything','something','about','or','related','to','what','was',
    'the','thing','earlier','before','previously','previous','my','issue'
  ];
  return text
    .toLowerCase()
    .replace(/[^\w\s]/g, ' ')
    .split(/\s+/)
    .filter(word => word && !stopWords.includes(word));
}

let answer = "I could not find anything earlier.";

if (
  currentMessage.includes('what did i ask') ||
  currentMessage.includes('what was my issue') ||
  currentMessage.includes('what was the thing i asked') ||
  currentMessage.includes('earlier') ||
  currentMessage.includes('previous')
) {
  if (lastUserMessage) {
    answer = `You earlier asked: "${lastUserMessage}"`;
  }
} else if (
  currentMessage.includes('did i ask') ||
  currentMessage.includes('related to')
) {
  const topicWords = extractTopic(currentMessage);

  const matchedMessage = userMessages.find(msg =>
    topicWords.some(word => msg.toLowerCase().includes(word))
  );

  if (matchedMessage) {
    answer = `Yes, you earlier asked: "${matchedMessage}"`;
  } else {
    answer = `No, I could not find an earlier user message about that.`;
  }
}

return [{
  json: {
    ...$json,
    answer
  }
}];

const userMessage = $json.message || '';
const assistantMessage = $json.final_response_text || '';
const attachmentSummary = $json.attachment_summary || '';

return [{
  json: {
    conversationId: $json.conversationId || '',
    user_message: userMessage,
    assistant_message: assistantMessage,
    intent: 'attachment_info_request',
    matched_issue: 'attachment_info_request',
    issue_summary: assistantMessage || attachmentSummary || userMessage,
    user_query: userMessage,
    attachment_summary: attachmentSummary,
    ticket_id: null,
    messageId: $json.messageId || ''
  }
}];

const attachmentSummary = ($json.attachment_summary || '').trim();
const attachmentText = ($json.attachment_text || '').trim();

let response = '';

if (!attachmentSummary && !attachmentText) {
  response = 'I could not extract readable content from the attachment. Please upload a clearer image or PDF.';
} else {
  response = attachmentSummary || attachmentText.slice(0, 1500);
}

return [{
  json: {
    ...$json,
    final_response_text: response,
    final_category: 'attachment_info_request',
    apiPayload: {
      response,
      sender: 'AI Assistant',
      category: 'attachment_info_request',
      originalMessageId: $json.messageId || '',
      conversationId: $json.conversationId || ''
    }
  }
}];

const llmOutput = $input.first().json;
const original = $('Prepare attachment info Memory').first().json;

const raw =
  llmOutput?.content?.parts?.[0]?.text ||
  llmOutput?.text ||
  llmOutput?.output ||
  '';

let cleaned = String(raw)
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    response: 'I could not clearly find that information in the attachment.',
    extracted_value: null,
    field_name: null
  };
}

return [{
  json: {
    conversationId: original.conversationId || '',
    user_message: original.user_message || '',
    assistant_message: parsed.response || 'I could not clearly find that information in the attachment.',
    intent: 'attachment_info_request',
    matched_issue: 'attachment_info_request',
    issue_summary: original.attachment_summary || original.user_message || '',
    user_query: original.user_message || '',
    attachment_summary: original.attachment_summary || '',
    ticket_id: null,
    messageId: original.messageId || '',
    final_response_text: parsed.response || 'I could not clearly find that information in the attachment.',
    extracted_value: parsed.extracted_value || null,
    field_name: parsed.field_name || null
  }
}];

const message = ($json.message || '').toLowerCase().trim();
const history = Array.isArray($json.history) ? $json.history : [];

function detectRequestedField(text) {
  if (/app(lication)? id|application number|app number/i.test(text)) return 'application id';
  if (/loan number|loan id/i.test(text)) return 'loan number';
  if (/status/i.test(text)) return 'status';
  if (/ifsc/i.test(text)) return 'ifsc';
  if (/bank name|bank/i.test(text)) return 'bank name';
  return null;
}

const requestedField = detectRequestedField(message);

let matchedMemory = null;

for (let i = history.length - 1; i >= 0; i--) {
  const h = history[i];
  const issueSummary = (h.issue_summary || '').toLowerCase();
  const attachmentSummary = (h.attachment_summary || '').toLowerCase();
  const assistantMessage = (h.assistant_message || '').toLowerCase();
  const userQuery = (h.user_query || '').toLowerCase();
  const userMessage = (h.user_message || '').toLowerCase();
  const matchedIssue = (h.matched_issue || '').toLowerCase();

  if (matchedIssue !== 'attachment_info_request') continue;

  if (requestedField) {
    if (
      issueSummary.includes(requestedField) ||
      attachmentSummary.includes(requestedField) ||
      assistantMessage.includes(requestedField) ||
      userQuery.includes(requestedField) ||
      userMessage.includes(requestedField)
    ) {
      matchedMemory = h;
      break;
    }
  } else {
    matchedMemory = h;
    break;
  }
}

return [{
  json: {
    ...$json,
    requested_field: requestedField,
    has_attachment_answer_in_memory: !!matchedMemory,
    attachment_answer_from_memory: matchedMemory
      ? (matchedMemory.assistant_message || matchedMemory.attachment_summary || matchedMemory.issue_summary || null)
      : null
  }
}];

