const llmOutput = $input.first().json;
const original = $('Merge Attachment Context1').first().json;

const raw = llmOutput?.content?.parts?.[0]?.text || llmOutput?.text || llmOutput?.output || '';

let cleaned = String(raw)
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    intent: 'unclear',
    confidence: 0,
    error_code: null,
    needs_ocr: false,
    direct_reply: null,
    normalized_user_need: 'Could not parse model output',
    needs_ticket: true
  };
}

return [{
  json: {
    ...original,
    parsed_intent: parsed
  }
}];

const reply = $json.parsed_intent?.direct_reply || 'Hello! How can I help you today?';

return [{
