let cleaned = String(raw)
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    matched_issue: 'no_match',
    short_resolution_or_hint: 'I could not confidently match this issue to the knowledge base.',
    confidence: 0,
    needs_ticket: true
  };
}

return [{
  json: {
    ...original,
    parsed_issue: parsed
  }
}];

const intent = $json.parsed_intent || {};
const issue = $json.parsed_issue || {};

const hasKbMatch = issue.matched_issue && issue.matched_issue !== 'no_match';

let response = '';

if (hasKbMatch) {
  response = issue.short_resolution_or_hint || 'I found a likely match for your issue.';
} else if (intent.needs_ocr) {
  response = 'I could not match this issue clearly yet. Please share a clearer screenshot or document showing the main error.';
} else {
  response = 'I could not find a clear match for this issue. Please share a little more detail.';
}

if (intent.intent === 'follow_up' && hasKbMatch) {
  response = `This looks like a follow-up to your earlier issue. ${response}`;
}

return [{
  json: {
    ...$json,
    final_response_text: response,
    final_category: hasKbMatch
      ? issue.matched_issue
      : (intent.intent || 'general_issue'),
    apiPayload: {
      response,
      sender: 'AI Assistant',
      category: hasKbMatch
        ? issue.matched_issue
        : (intent.intent || 'general_issue'),
      originalMessageId: $json.messageId || '',
      conversationId: $json.conversationId || ''
    }
  }
}];

const intent = $json.parsed_intent || {};
const issue = $json.parsed_issue || {};
const message = ($json.message || '').trim();
const lowerMessage = message.toLowerCase();
const existingTicketId = $json.latest_ticket_id || null;
const history = Array.isArray($json.history) ? $json.history : [];

const wantsSupportPerson =
  /contact support|support person|human support|talk to support|connect me to support|connect to support|agent|human agent|representative|real person|customer care|escalate/i.test(lowerMessage);

const asksForTicketId =
  /ticket id|existing ticket|my ticket|previous ticket|show ticket|ticket number/i.test(lowerMessage);

const genericSupportOnly =
  /^(i want to contact support|contact support|connect me to support|connect to support|i need support|support|human|agent|human agent|representative|real person|customer care|escalate)$/i.test(lowerMessage);

const awaitingTicketDetails = history.some(item =>
  item.role === 'assistant' &&
  /please briefly describe.*issue.*ticket|tell me your issue.*create.*ticket|describe the issue so i can create/i.test(
    (item.assistant_message || item.message || item.text || '').toLowerCase()
  )
);

const hasIssueDetails =
  message.length > 20 &&
  !genericSupportOnly;

const hasManualTicketInThisChat = history.some(h =>
  h.ticket_id &&
  (h.matched_issue === 'manual_ticket' || h.matched_issue === 'existing_ticket_reused')
);

const reuseExistingTicket =
  !!existingTicketId &&
  hasManualTicketInThisChat &&
  (
    wantsSupportPerson ||
    asksForTicketId ||
    issue.matched_issue === 'no_match'
  );

let shouldAskForDetails = false;
let shouldCreateTicket = false;
let ticketReason = null;

if (wantsSupportPerson && !hasIssueDetails) {
  shouldAskForDetails = true;
  ticketReason = 'support_requested_but_no_issue_details';
}

if (wantsSupportPerson && hasIssueDetails) {
  shouldCreateTicket = true;
  ticketReason = 'support_requested_with_issue_details';
}

if (!wantsSupportPerson && awaitingTicketDetails && hasIssueDetails) {
  shouldCreateTicket = true;
  shouldAskForDetails = false;
  ticketReason = 'issue_details_provided_after_support_request';
}

if (!wantsSupportPerson && !asksForTicketId && !shouldCreateTicket && !reuseExistingTicket) {
  shouldCreateTicket = true;
  ticketReason = 'default_manual_ticket';
}

const routeToExistingResponse = reuseExistingTicket || shouldAskForDetails || asksForTicketId;

// hardcoded routing for now; replace with your real mapping later
const assignedTo = 'dev1';
const assignedToName = 'Developer 1';
const assignedTeamsWebhook = 'https://YOUR-ASSIGNEE-TEAMS-WEBHOOK';
const escalationTo = 'manager1';
const escalationToName = 'Engineering Manager';
const escalationTeamsWebhook = 'https://YOUR-MANAGER-TEAMS-WEBHOOK';

return [{
  json: {
    ...$json,
    conversationId: $json.conversationId || '',
    wantsSupportPerson,
    asksForTicketId,
    genericSupportOnly,
    hasIssueDetails,
    awaitingTicketDetails,
    shouldAskForDetails,
    shouldCreateTicket,
    ticketReason,
    reuse_existing_ticket: reuseExistingTicket,
    route_to_existing_response: routeToExistingResponse,
    existing_ticket_id: reuseExistingTicket ? existingTicketId : null,
    assigned_to: assignedTo,
    assigned_to_name: assignedToName,
    assigned_teams_webhook: assignedTeamsWebhook,
    escalation_to: escalationTo,
    escalation_to_name: escalationToName,
    escalation_teams_webhook: escalationTeamsWebhook,
    ticketPayload: {
      ticket_title: intent.error_code
        ? `Issue related to ${intent.error_code}`
        : (
            issue.matched_issue &&
            issue.matched_issue !== 'no_match'
              ? issue.matched_issue
              : 'Manual support ticket'
          ),
      ticket_description:
        intent.normalized_user_need ||
        $json.attachment_summary ||
        $json.message ||
        'Manual support review needed',
      category:
        issue.matched_issue &&
        issue.matched_issue !== 'no_match'
          ? issue.matched_issue
          : 'manual_ticket',
      priority: intent.intent === 'error_code_issue' ? 'High' : 'Medium',
      assigned_to: assignedTo,
      assigned_to_name: assignedToName,
      escalation_to: escalationTo,
      escalation_to_name: escalationToName,
      created_from_conversation: $json.conversationId || '',
      original_message: $json.message || ''
    },
    messageId: $json.messageId || '',
    originalCategory:
      issue.matched_issue &&
      issue.matched_issue !== 'no_match'
        ? issue.matched_issue
        : (intent.intent || 'general_issue'),
    originalMessage: $json.message || '',
    originalIntent: intent.intent || 'general_issue',
    issue_summary:
      issue.matched_issue &&
      issue.matched_issue !== 'no_match'
        ? issue.matched_issue
        : (intent.normalized_user_need || $json.attachment_summary || $json.message || '')
  }
}];

const ticketId = $json.existing_ticket_id || null;
const originalMessage = ($json.originalMessage || '').toLowerCase();

let response = '';
let category = 'existing_ticket_reused';
let finalTicketId = ticketId;

if ($json.shouldAskForDetails) {
  response = 'Sure, please briefly describe the issue so I can create the right support ticket.';
  category = 'support_request_pending_details';
  finalTicketId = null;
} else if ($json.asksForTicketId && !ticketId) {
  response = 'I could not find an existing support ticket in this chat.';
  category = 'ticket_lookup_not_found';
  finalTicketId = null;
} else if (ticketId) {
  response = `You already have an active support ticket for this chat. Ticket ID: ${ticketId}.`;

  if (/ticket id|my ticket|existing ticket|ticket number/i.test(originalMessage)) {
    response = `Your existing support ticket ID is ${ticketId}.`;
  }
}

return [{
  json: {
    ...$json,
    final_response_text: response,
    final_category: category,
    final_ticket_id: finalTicketId,
    apiPayload: {
      response,
      sender: 'AI Assistant',
      category,
      originalMessageId: $json.messageId || '',
      conversationId: $json.conversationId || '',
      ticket_id: finalTicketId
    }
  }
}];

return [{
  json: {
    conversationId: $json.conversationId || '',
