const lookupResult = $input.first().json;
const original = $('Is Followup Support?').first().json;

const ticketId =
  lookupResult.ticket_id ||
  original.latest_ticket_id ||
  null;

const previousDescription =
  lookupResult.ticket?.description ||
  original.latest_ticket_message ||
  '';

const latestUserMessage = original.message || '';

const mergedDescription = [
  previousDescription ? `Previous: ${previousDescription}` : '',
  latestUserMessage ? `Follow-up: ${latestUserMessage}` : ''
].filter(Boolean).join('\n\n');

const assignedTo = 'dev1';
const assignedToName = 'Developer 1';

let chatResponse = '';
if (!ticketId) {
  chatResponse = 'I could not find an existing ticket for this conversation. Please describe your issue so I can create a new one.';
} else {
  chatResponse = `Your follow-up has been recorded on Ticket ID: ${ticketId}. The support team has been notified.`;
}

return [{
  json: {
    ...original,
    followup_ticket_id: ticketId,
    previous_ticket_description: previousDescription,
    latest_user_message: latestUserMessage,
    merged_description: mergedDescription,
    assigned_to: assignedTo,
    assigned_to_name: assignedToName,
    has_ticket: !!ticketId,
    followup_chat_response: chatResponse,
    followupPayload: ticketId ? {
      ticket_id: ticketId,
      conversationId: original.conversationId || '',
      latest_user_message: latestUserMessage,
      previous_ticket_description: previousDescription,
      merged_description: mergedDescription,
      assigned_to: assignedTo,
      assigned_to_name: assignedToName,
      category: 'followup_support'
    } : null,
    teamsFollowupPayload: ticketId ? {
      '@type': 'MessageCard',
      '@context': 'http://schema.org/extensions',
      summary: `Ticket follow-up: ${ticketId}`,
      themeColor: 'FFA500',
      title: 'Ticket Follow-Up',
      text: `CHAT_CONVERSATION_ID: ${original.conversationId || 'N/A'}`,
      sections: [
        {
          facts: [
            { name: 'Ticket ID', value: ticketId },
            { name: 'Status', value: 'Follow-Up' },
            { name: 'Latest Message', value: latestUserMessage || 'N/A' },
            { name: 'Previous Description', value: previousDescription ? previousDescription.slice(0, 200) : 'N/A' },
            { name: 'Assigned To', value: assignedToName }
          ]
        }
      ]
    } : null,
    apiPayload: {
      response: chatResponse,
      sender: 'AI Assistant',
      category: 'followup_support',
      originalMessageId: original.messageId || '',
      conversationId: original.conversationId || '',
      ticket_id: ticketId
    }
  }
}];
